:"부재료"},{"ingredient_seq":3960,"ingredient_name":"소금","ingredient_quantity":"약간","ingredient_type_code":"3060003","ingredient_type_name":"양념"},{"ingredient_seq":3961,"ingredient_name":"흰후추","ingredient_quantity":"약간","ingredient_type_code":"3060003","ingredient_type_name":"양념"},{"ingredient_seq":3962,"ingredient_name":"바질","ingredient_quantity":"약간","ingredient_type_code":"3060003","ingredient_type_name":"양념"},{"ingredient_seq":3963,"ingredient_name":"오레가노","ingredient_quantity":"약간","ingredient_type_code":"3060003","ingredient_type_name":"양념"}]},{"recipe_id":"epis:358","recipe_name_ko":"삼색태극말이초밥","provider":"농림수산식품교육문화정보원","source_url":"https://www.data.go.kr/data/15057205/openapi.do","source_dataset_url":"https://www.data.go.kr/data/15057205/openapi.do","license":"이용허락범위 제한 없음","retrieved_on":"2026-11-23","raw_ingredients":"김 5장\n계란노른자 3개\n오보로 2큰술\n파슬리 2큰술\n밥 1공기\n식초 1과1/2큰술\n설탕 2/3큰술\n소금 1/4큰술","source_recipe":{"ROW_NUM":358,"RECIPE_ID":358,"RECIPE_NM_KO":"삼색태극말이초밥","SUMRY":"피크닉을 위해 준비할 수 있는 깜찍한 요리.","NATION_CODE":"3020003","NATION_NM":"일본","TY_CODE":"3010001","TY_NM":"밥","COOKING_TIME":"30분","CALORIE":"345Kcal","QNT":"2인분","LEVEL_NM":"보통","IRDNT_CODE":"곡류","PC_NM":"10,000원"},"ingredients":[{"ingredient_seq":3964,"ingredient_name":"김","ingredient_quantity":"5장","ingredient_type_code":"3060001","ingredient_type_name":"주재료"},{"ingredient_seq":3965,"ingredient_name":"계란노른자","ingredient_quantity":"3개","ingredient_type_code":"3060002","ingredient_type_name":"부재료"},{"ingredient_seq":3966,"ingredient_name":"오보로","ingredient_quantity":"2큰술","ingredient_type_code":"3060002","ingredient_type_name":"부재료"},{"ingredient_seq":3967,"ingredient_name":"파슬리","ingredient_quantity":"2큰술","ingredient_type_code":"3060003","ingredient_type_name":"양념"},{"ingredient_seq":3968,"ingredient_name":"밥","ingredient_quantity":"1공기","ingredient_type_code":"3060001","ingredient_type_name":"주재료"},{"ingredient_seq":3969,"ingredient_name":"식초","ingredient_quantity":"1과1/2큰술","ingredient_type_code":"3060003","ingredient_type_name":"양념"},{"ingredient_seq":3970,"ingredient_name":"설탕","ingredient_quantity":"2/3큰술","ingredient_type_code":"3060003","ingredient_type_name":"양념"},{"ingredient_seq":3971,"ingredient_name":"소금","ingredient_quantity":"1/4큰술","ingredient_type_code":"3060003","ingredient_type_name":"양념"}]}]'::jsonb;
  schema_check record;
  unexpected text;
BEGIN
-- K-Food: EPIS import: 179 recipes / 1952 ingredient rows. Orphan rows are quarantined separately.
-- Run once in Supabase SQL Editor as project owner. Re-running does not overwrite existing rows.
-- Source: https://www.data.go.kr/data/15057205/openapi.do
-- License: 이용허락범위 제한 없음. All ingredient links remain needs_review.
-- Existing ingredient_master and allergen evidence are NOT updated.
-- No DELETE, UPDATE, service key, or public write policy is used.

-- Fail atomically if a required, unknown column would prevent import.

  FOR schema_check IN SELECT * FROM (VALUES
    ('external_recipes',ARRAY['recipe_id','recipe_name_ko']::text[]),
    ('external_recipe_ingredients',ARRAY['recipe_id','ingredient_seq','ingredient_name','ingredient_quantity','ingredient_type_code','ingredient_type_name']::text[]),
    ('external_ingredient_master_mapping',ARRAY['source_ingredient_name','ingredient_id','mapping_status','notes']::text[])
  ) AS t(table_name,cols)
  LOOP
    IF to_regclass('public.'||schema_check.table_name) IS NULL THEN RAISE EXCEPTION 'Missing table: %',schema_check.table_name; END IF;
    SELECT string_agg(c.column_name,', ') INTO unexpected FROM information_schema.columns c
      WHERE c.table_schema='public' AND c.table_name=schema_check.table_name AND c.is_nullable='NO'
      AND c.column_default IS NULL AND c.is_identity='NO' AND c.is_generated='NEVER'
      AND NOT(c.column_name=ANY(schema_check.cols));
    IF unexpected IS NOT NULL THEN RAISE EXCEPTION 'Schema check: %. Required columns need values: %',schema_check.table_name,unexpected; END IF;
  END LOOP;




-- Refuse collisions rather than mix our seed into an existing, different recipe.

  IF EXISTS(
    SELECT 1 FROM jsonb_array_elements(kfood_payload) r
    JOIN public.external_recipes e ON e.recipe_id=r->>'recipe_id'
    WHERE e.recipe_name_ko IS DISTINCT FROM r->>'recipe_name_ko'
  ) THEN RAISE EXCEPTION 'Recipe ID collision: existing name differs. No data changed.'; END IF;
  IF EXISTS(
    SELECT 1 FROM jsonb_array_elements(kfood_payload) r
    CROSS JOIN LATERAL jsonb_array_elements(r->'ingredients') i
    JOIN public.external_recipe_ingredients e ON e.recipe_id=r->>'recipe_id' AND e.ingredient_seq=(i->>'ingredient_seq')::integer
    WHERE e.ingredient_name IS DISTINCT FROM i->>'ingredient_name'
       OR e.ingredient_quantity IS DISTINCT FROM i->>'ingredient_quantity'
  ) THEN RAISE EXCEPTION 'Recipe ingredient collision: existing content differs. No data changed.'; END IF;


INSERT INTO public.external_recipes(recipe_id,recipe_name_ko)
SELECT r->>'recipe_id',r->>'recipe_name_ko'
FROM jsonb_array_elements(kfood_payload) r
ON CONFLICT(recipe_id) DO NOTHING;

INSERT INTO public.external_recipe_ingredients(recipe_id,ingredient_seq,ingredient_name,ingredient_quantity,ingredient_type_code,ingredient_type_name)
SELECT r->>'recipe_id',(i->>'ingredient_seq')::integer,i->>'ingredient_name',i->>'ingredient_quantity',NULLIF(i->>'ingredient_type_code',''),NULLIF(i->>'ingredient_type_name','')
FROM jsonb_array_elements(kfood_payload) r
CROSS JOIN LATERAL jsonb_array_elements(r->'ingredients') i
ON CONFLICT(recipe_id,ingredient_seq) DO NOTHING;

-- Exact name first. Whitespace-only equivalence is accepted only when unique.
-- No synonyms, substring matching, or clinical inference.
WITH names AS (
  SELECT DISTINCT i->>'ingredient_name' AS name
  FROM jsonb_array_elements(kfood_payload) r
  CROSS JOIN LATERAL jsonb_array_elements(r->'ingredients') i
), candidates AS (
  SELECT n.name,
    CASE WHEN count(*) FILTER(WHERE im.ingredient_name=n.name)=1
      THEN min(im.id::text) FILTER(WHERE im.ingredient_name=n.name)::uuid
      WHEN count(*) FILTER(WHERE im.ingredient_name=n.name)=0 AND count(im.id)=1
      THEN min(im.id::text)::uuid ELSE NULL END AS ingredient_id
  FROM names n LEFT JOIN public.ingredient_master im
    ON regexp_replace(im.ingredient_name,'[[:space:]]','','g')=regexp_replace(n.name,'[[:space:]]','','g')
  GROUP BY n.name
)
INSERT INTO public.external_ingredient_master_mapping(source_ingredient_name,ingredient_id,mapping_status,notes)
SELECT name,ingredient_id,'needs_review',
  CASE WHEN ingredient_id IS NULL THEN 'No unique name match. Do not infer allergen absence. '
       ELSE 'Name identity match only. Product composition and allergen evidence need review. ' END
  || 'EPIS recipe name identity only; https://www.data.go.kr/data/15057205/openapi.do'
FROM candidates ON CONFLICT(source_ingredient_name) DO NOTHING;

-- Keep raw ingredients, license and attribution alongside imported records.
CREATE TABLE IF NOT EXISTS public.kfood_public_recipe_sources(
  recipe_id text PRIMARY KEY, provider text NOT NULL, source_url text NOT NULL,
  dataset_url text NOT NULL, license_note text NOT NULL, raw_ingredients text NOT NULL,
  retrieved_on date NOT NULL, verification_status text NOT NULL DEFAULT 'needs_review'
);
ALTER TABLE public.kfood_public_recipe_sources ADD COLUMN IF NOT EXISTS source_record jsonb;
INSERT INTO public.kfood_public_recipe_sources(recipe_id,provider,source_url,dataset_url,license_note,raw_ingredients,retrieved_on,source_record)
SELECT r->>'recipe_id',r->>'provider',r->>'source_url',r->>'source_dataset_url',r->>'license',r->>'raw_ingredients',(r->>'retrieved_on')::date,jsonb_build_object('recipe',r->'source_recipe','ingredients',r->'ingredients')
FROM jsonb_array_elements(kfood_payload) r
ON CONFLICT(recipe_id) DO NOTHING;
